Plan: Read the cached score values from Sheet1, count how many times each player’s row contains the maximum score in each game column B:G, and write those counts as plain integers into H2:H8.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

first_row = 2
last_row = max(8, vws.max_row)
first_col = 2  # B
last_col = 7   # G

def as_number(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except Exception:
            return None
    return None

counts = {}

for r in range(first_row, last_row + 1):
    count = 0
    for c in range(first_col, last_col + 1):
        col_values = []
        for rr in range(first_row, last_row + 1):
            n = as_number(vws.cell(row=rr, column=c).value)
            if n is not None:
                col_values.append(n)

        if col_values:
            max_value = max(col_values)
            row_value = as_number(vws.cell(row=r, column=c).value)
            if row_value is not None and row_value == max_value:
                count += 1

    ws.cell(row=r, column=8).value = count
    counts[vws.cell(row=r, column=1).value] = count

wb.save(OUT)

print("Computed win counts:", counts)
